const FILE_TOOLS = new Set(['Read', 'Write', 'Edit', 'MultiEdit', 'NotebookEdit']);
const SHELL_TOOLS = new Set(['Bash', 'PowerShell']);
const PATH_TOOLS = new Set(['Grep', 'Glob']);
const PLAN_TOOLS = new Set(['TodoWrite', 'TaskCreate', 'TaskUpdate', 'update_plan']);
const STEP_STATUS = new Set(['pending', 'in_progress', 'completed', 'deleted']);

function lengthOf(v         )         {
  if (v === null || v === undefined) return 0;
  if (typeof v === 'string') return v.length;
  return JSON.stringify(v).length;
}

function asObject(v         )      {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v       ) : {};
}

function pick(raw     , keys          )      {
  const out      = {};
  for (const k of keys) if (raw[k] !== undefined) out[k] = raw[k];
  return out;
}

function strings(raw     , keys          )      {
  return Object.fromEntries(keys.filter((k) => typeof raw[k] === 'string').map((k) => [k, (raw[k]          ).slice(0, 4096)]));
}

const WORD = /^[a-z_]{1,40}$/;

/** A Stop's background_tasks as at most 50 `{type, status}` pairs of plain words; ids and descriptions never pass. */
function backgroundTasks(v         )      {
  if (!Array.isArray(v)) return {};
  const tasks = v.slice(0, 50).map(asObject).filter((t) => typeof t.type === 'string' && WORD.test(t.type) && typeof t.status === 'string' && WORD.test(t.status)).map((t) => ({ type: t.type, status: t.status }));
  return { background_tasks: tasks };
}

/** An opencode state plugin report: state, why, seq and the root session id; nothing unless both state and seq are valid. */
function opencodeState(r     )      {
  // A seq more than a day ahead of Date.now() * 1000 is refused.
  if (!['working', 'waiting', 'done'].includes(r.state          ) || !Number.isSafeInteger(r.seq) || (r.seq          ) > (Date.now() + 86_400_000) * 1000) return {};
  return {
    state: r.state,
    ...(['permission', 'error'].includes(r.why          ) ? { why: r.why } : {}),
    seq: r.seq,
    ...strings(r, ['session_id']),
  };
}

const stepText = (v         ) => (typeof v === 'string' ? redactCredentials(v).replace(/\s+/g, ' ').trim().slice(0, 200) : '');

/** At most 30 `{text, status}` steps: text credential-scrubbed and capped at 200 characters, status from a fixed set (`done: true` reads as completed). */
export function stepItems(v         )                                          {
  if (!Array.isArray(v)) return [];
  return v.slice(0, 30).map(asObject).map((t) => ({
    text: stepText([t.text, t.content, t.step, t.subject].find((x) => typeof x === 'string')),
    status: STEP_STATUS.has(t.status          ) ? (t.status          ) : t.done === true ? 'completed' : 'pending',
  })).filter((t) => t.text);
}

/** A plan tool's input as its step items; TaskUpdate keeps only a 1-4 digit taskId, its status and its new subject. Applying it to its own output changes nothing. */
function planInput(toolName        , o     )      {
  if (toolName === 'TaskUpdate') {
    const id = typeof o.taskId === 'number' || typeof o.taskId === 'string' ? String(o.taskId) : '';
    const text = stepText(o.subject ?? o.text);
    return { ...(/^\d{1,4}$/.test(id) ? { taskId: id } : {}), ...(STEP_STATUS.has(o.status          ) ? { status: o.status } : {}), ...(text ? { text } : {}) };
  }
  const list = Array.isArray(o.items) ? o.items : toolName === 'TaskCreate' ? [o] : toolName === 'TodoWrite' ? o.todos : o.plan;
  return { items: stepItems(list) };
}

/** Redacts a Claude tool_input per the table in contracts/events-and-hooks.md. */
export function redactToolInput(toolName        , input         )      {
  const o = asObject(input);
  if (PLAN_TOOLS.has(toolName)) return planInput(toolName, o);
  if (SHELL_TOOLS.has(toolName)) {
    const cmd = typeof o.command === 'string' ? o.command : '';
    const words = cmd.trim().split(/\s+/).filter((w) => !/^[A-Za-z_][A-Za-z0-9_]*=/.test(w));
    const word = words[0] ?? '';
    const eq = word.indexOf('=');
    return { first_word: eq >= 0 ? word.slice(0, eq) : word, length: cmd.length };
  }
  if (FILE_TOOLS.has(toolName)) return typeof o.file_path === 'string' ? { file_path: o.file_path } : {};
  if (PATH_TOOLS.has(toolName)) return typeof o.path === 'string' ? { path: o.path } : {};
  if (toolName === 'WebFetch') {
    try {
      return { host: new URL(String(o.url)).host };
    } catch {
      return { host: '' };
    }
  }
  const lengths                         = {};
  for (const k of Object.keys(o)) lengths[k] = lengthOf(o[k]);
  return lengths;
}

function classifyNotification(type         , message        )                                            {
  if (type === 'permission_prompt') return 'permission';
  if (type === 'idle_prompt') return 'idle';
  if (type === 'agent_needs_input' || (typeof type === 'string' && /^elicitation_(url_)?dialog$/.test(type))) return 'input';
  if (typeof type === 'string' && type) return 'other';
  if (/permission|allow|approve|wants to use/i.test(message)) return 'permission';
  if (/waiting for (your )?input|waiting for you|idle/i.test(message)) return 'idle';
  return 'other';
}

/** Builds an event payload from an explicit per-kind allowlist; any other field is dropped. */
export function buildPayload(kind        , raw        )      {
  const r = asObject(raw);
  const tool = ()      => ({
    ...strings(r, ['session_id', 'transcript_path', 'cwd', 'tool_name', 'tool_use_id']),
    tool_input: redactToolInput(String(r.tool_name ?? ''), r.tool_input),
  });
  switch (kind) {
    case 'launch':
      return pick(r, ['session_id', 'pid', 'cwd', 'engine', 'started_at']);
    case 'claude.PreToolUse':
    case 'claude.PermissionRequest':
    case 'claude.PostToolUseFailure':
    case 'codex.PreToolUse':
    case 'codex.PostToolUse':
      return tool();
    case 'claude.PostToolUse':
      return { ...tool(), response_length: lengthOf(r.tool_response) };
    case 'core.steps':
      return { items: stepItems(r.items) };
    case 'claude.UserPromptSubmit':
      return { ...strings(r, ['session_id', 'transcript_path', 'cwd']), prompt_length: lengthOf(r.prompt) };
    case 'claude.Notification': {
      const msg = typeof r.message === 'string' ? r.message : '';
      return { ...strings(r, ['session_id', 'cwd', 'notification_type']), class: classifyNotification(r.notification_type, msg), message_length: msg.length };
    }
    case 'claude.Stop':
      return { ...strings(r, ['session_id', 'transcript_path', 'cwd']), ...(typeof r.stop_hook_active === 'boolean' ? { stop_hook_active: r.stop_hook_active } : {}), ...backgroundTasks(r.background_tasks) };
    case 'claude.StopFailure':
      return strings(r, ['session_id', 'transcript_path', 'cwd', 'error_type']);
    case 'claude.SessionEnd':
      return strings(r, ['session_id', 'cwd', 'reason']);
    case 'codex.turn':
      return {
        ...strings(r, ['type', 'thread-id', 'turn-id', 'cwd']),
        input_length: lengthOf(r['input-messages']),
        reply_length: lengthOf(r['last-assistant-message']),
      };
    case 'core.activity':
      return pick(r, ['state', 'changed_at', 'session_id']);
    case 'codex.SessionStart':
    case 'codex.PermissionRequest':
    case 'codex.Stop':
    case 'codex.Interrupt':
    case 'gemini.SessionStart':
    case 'gemini.BeforeAgent':
    case 'gemini.AfterTool':
    case 'gemini.Notification':
    case 'gemini.AfterAgent':
      return strings(r, ['session_id', 'transcript_path', 'cwd', 'tool_name', 'notification_type', 'source']);
    case 'core.process-gone':
      return pick(r, ['pid']);
    case 'opencode.state':
      return opencodeState(r);
    default:
      return {};
  }
}

const SPOOL_KINDS = new Set(['claude.PreToolUse', 'claude.PostToolUse', 'claude.PermissionRequest', 'claude.PostToolUseFailure', 'claude.UserPromptSubmit', 'claude.Notification', 'claude.Stop', 'claude.StopFailure', 'claude.SessionEnd', 'codex.turn']);
const CLASSES = new Set(['permission', 'input', 'idle', 'other']);

export function spoolKind(kind        )          {
  return SPOOL_KINDS.has(kind);
}

export function spoolKinds()           {
  return [...SPOOL_KINDS];
}

function redactedToolInput(toolName        , input         )      {
  const o = asObject(input);
  const s = (v         , max        ) => (typeof v === 'string' ? v.slice(0, max) : '');
  const n = (v         ) => (typeof v === 'number' && Number.isFinite(v) ? v : 0);
  if (PLAN_TOOLS.has(toolName)) return planInput(toolName, o);
  if (SHELL_TOOLS.has(toolName)) return { first_word: s(o.first_word, 200).split(/\s/)[0], length: n(o.length) };
  if (FILE_TOOLS.has(toolName)) return typeof o.file_path === 'string' ? { file_path: s(o.file_path, 4096) } : {};
  if (PATH_TOOLS.has(toolName)) return typeof o.path === 'string' ? { path: s(o.path, 4096) } : {};
  if (toolName === 'WebFetch') return { host: s(o.host, 253).split(/[/\s]/)[0] };
  const lengths                         = {};
  for (const k of Object.keys(o).slice(0, 50)) lengths[k.slice(0, 100)] = n(o[k]);
  return lengths;
}

/** Re-checks a payload a sandboxed writer already built: same fields as buildPayload's output, typed and capped, tool_input in its redacted shape. */
export function rebuildPayload(kind        , built        )      {
  const b = asObject(built);
  const strs = (keys          )      => Object.fromEntries(keys.filter((k) => typeof b[k] === 'string').map((k) => [k, (b[k]          ).slice(0, 4096)]));
  const n = (k        ) => (typeof b[k] === 'number' && Number.isFinite(b[k]) ? b[k] : 0);
  const tool = ()      => ({ ...strs(['session_id', 'transcript_path', 'cwd', 'tool_name', 'tool_use_id']), tool_input: redactedToolInput(String(b.tool_name ?? ''), b.tool_input) });
  switch (kind) {
    case 'claude.PreToolUse':
    case 'claude.PermissionRequest':
    case 'claude.PostToolUseFailure':
      return tool();
    case 'claude.PostToolUse':
      return { ...tool(), response_length: n('response_length') };
    case 'claude.UserPromptSubmit':
      return { ...strs(['session_id', 'transcript_path', 'cwd']), prompt_length: n('prompt_length') };
    case 'claude.Notification':
      return { ...strs(['session_id', 'cwd', 'notification_type']), class: CLASSES.has(b.class          ) ? b.class : 'other', message_length: n('message_length') };
    case 'claude.Stop':
      return { ...strs(['session_id', 'transcript_path', 'cwd']), stop_hook_active: b.stop_hook_active === true, ...backgroundTasks(b.background_tasks) };
    case 'claude.StopFailure':
      return strs(['session_id', 'transcript_path', 'cwd', 'error_type']);
    case 'claude.SessionEnd':
      return strs(['session_id', 'cwd', 'reason']);
    case 'codex.turn':
      return { ...strs(['type', 'thread-id', 'turn-id', 'cwd']), input_length: n('input_length'), reply_length: n('reply_length') };
    case 'opencode.state':
      return opencodeState(b);
    default:
      return {};
  }
}

const NOTIFY_LABEL                         = {
  gate: 'approval needed', approval: 'approval needed', handoff: 'handoff waiting', 'run-failed': 'run failed', budget: 'budget limit', 'missing-secret': 'secret missing', other: 'needs you',
};

/** The one-line message a notification sink receives: a fixed label plus the item text with URLs, paths and token-like strings removed. */
export function notifyText(kind        , text        )         {
  const clean = redactCredentials(maskTokens(text))
    .replace(/\s+/g, ' ')
    .replace(/https?:\/\/\S+/g, '<url>')
    .replace(/[A-Za-z]:[\\/]\S*|(?<!\S)\/[^\s/]+\/\S*/g, '<path>')
    .replace(/[A-Za-z0-9_+=-]{24,}/g, '<redacted>')
    .trim()
    .slice(0, 160);
  return `cc (${NOTIFY_LABEL[kind] ?? 'needs you'}): ${clean}`;
}

                                                                                              

/** Known token shapes. A rule's regex runs only when the text holds one of its keywords; a match is masked when its entropy reaches min_entropy bits per character. */
export const TOKEN_RULES              = [
  { id: 'github', keywords: ['ghp_', 'gho_', 'ghu_', 'ghs_', 'ghr_'], re: /\bgh[pousr]_[A-Za-z0-9]{30,}/g, min_entropy: 3 },
  { id: 'github-pat', keywords: ['github_pat_'], re: /\bgithub_pat_\w{20,}/g, min_entropy: 3 },
  { id: 'anthropic', keywords: ['sk-ant-'], re: /\bsk-ant-[A-Za-z0-9_-]{20,}/g, min_entropy: 3 },
  { id: 'openai-project', keywords: ['sk-proj-'], re: /\bsk-proj-[A-Za-z0-9_-]{20,}/g, min_entropy: 3 },
  { id: 'openai', keywords: ['sk-'], re: /\bsk-[A-Za-z0-9_-]{20,}/g, min_entropy: 3 },
  { id: 'aws', keywords: ['AKIA'], re: /\bAKIA[0-9A-Z]{16}\b/g, min_entropy: 3 },
  { id: 'slack', keywords: ['xox'], re: /\bxox[abprs]-[A-Za-z0-9-]{10,}/g, min_entropy: 3 },
  { id: 'google-api', keywords: ['AIza'], re: /\bAIza[0-9A-Za-z_-]{35}/g, min_entropy: 3 },
  { id: 'jwt', keywords: ['eyJ'], re: /\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]*/g, min_entropy: 3 },
  { id: 'private-key', keywords: ['PRIVATE KEY'], re: /-----BEGIN [A-Z ]*PRIVATE KEY-----/g, min_entropy: 0 },
  { id: 'stripe', keywords: ['sk_live_', 'rk_live_'], re: /\b[sr]k_live_[A-Za-z0-9]{20,}/g, min_entropy: 3 },
  { id: 'gitlab', keywords: ['glpat-'], re: /\bglpat-[A-Za-z0-9_-]{20,}/g, min_entropy: 3 },
  { id: 'npm', keywords: ['npm_'], re: /\bnpm_[A-Za-z0-9]{36,}/g, min_entropy: 3 },
  { id: 'pypi', keywords: ['pypi-'], re: /\bpypi-[A-Za-z0-9_-]{50,}/g, min_entropy: 3 },
  { id: 'huggingface', keywords: ['hf_'], re: /\bhf_[A-Za-z0-9]{30,}/g, min_entropy: 3 },
  { id: 'google-oauth', keywords: ['ya29.'], re: /\bya29\.[A-Za-z0-9_-]{20,}/g, min_entropy: 3 },
  { id: 'azure-storage', keywords: ['AccountKey='], re: /AccountKey=[A-Za-z0-9+/]{40,}={0,2}/g, min_entropy: 3 },
  { id: 'sendgrid', keywords: ['SG.'], re: /\bSG\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}/g, min_entropy: 3 },
  { id: 'bearer', keywords: ['Bearer'], re: /\bBearer\s+[A-Za-z0-9._~+/=-]{20,}/g, min_entropy: 3 },
];

/** Shannon entropy of s in bits per character. */
function entropy(s        )         {
  const counts = new Map                ();
  for (const char of s) counts.set(char, (counts.get(char) ?? 0) + 1);
  let bits = 0;
  for (const count of counts.values()) bits -= (count / s.length) * Math.log2(count / s.length);
  return bits;
}

/** Replaces each known-shape token in text with [token]; SHAs, UUIDs and paths match no rule and are kept. */
export function maskTokens(text        )         {
  let out = text;
  for (const rule of TOKEN_RULES) {
    if (!rule.keywords.some((k) => out.includes(k))) continue;
    out = out.replace(rule.re, (m) => (entropy(m) >= rule.min_entropy ? '[token]' : m));
  }
  return out;
}

/** The TOKEN_RULES regexes without the global flag, for approvals' credential check. */
export const CREDENTIAL_PATTERNS           = TOKEN_RULES.map((r) => new RegExp(r.re.source));

/** A run of 32+ token characters is a credential when it mixes digits, lower and upper case; found in one pass, then each run tested, so a long run costs linear time. */
const LONG_RUN = /[A-Za-z0-9_+/=-]{32,}/g;
const mixedCase = (run        ) => /[0-9]/.test(run) && /[a-z]/.test(run) && /[A-Z]/.test(run);

const ENTROPY_RUN = /[A-Za-z0-9_-]{24,}/g;

function highEntropy(run        )          {
  if (!/[0-9]/.test(run) || !/[a-z]/.test(run)) return false;
  if (/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/.test(run) || /^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(run)) return false;
  if (/^(?:[A-Za-z]+|[0-9]+)(?:[_-](?:[A-Za-z]+|[0-9]+))*$/.test(run)) return false;
  return entropy(run) >= 3.5;
}

export function looksLikeCredential(text        )          {
  return CREDENTIAL_PATTERNS.some((re) => re.test(text)) || (text.match(LONG_RUN) ?? []).some(mixedCase);
}

/** Replaces every credential-pattern match in text with [secret]. */
export function redactCredentials(text        )         {
  return CREDENTIAL_PATTERNS.reduce((out, re) => out.replace(new RegExp(re.source, 'g'), '[secret]'), text)
    .replace(LONG_RUN, (run) => (mixedCase(run) ? '[secret]' : run))
    .replace(ENTROPY_RUN, (run) => (highEntropy(run) ? '[secret]' : run));
}

/** Replaces every known secret value in text; values under 4 characters are left alone so short words survive. */
/** Shorter values are not redacted: they would match ordinary words. A browser secret must be at least this long. */
export const MIN_SECRET_LENGTH = 4;

export function redactSecretValues(text        , values                  )         {
  let out = text;
  for (const v of [...values].sort((a, b) => b.length - a.length)) if (v.length >= MIN_SECRET_LENGTH) out = out.split(v).join('[secret]');
  return out;
}

const TOKEN_KEY = /^(access_?token|refresh_?token|id_?token|token|auth|authorization|api_?key|apikey|key|secret|client_secret|password|passwd|pwd|session|sessionid|sid|sig|signature|code)$/i;
const ASSIGNMENT_KEY = /password|passwd|(?:^|[_.-])pass(?:$|[_.-])|pwd|secret|token|api_?key|access_key|private_key|credential|authorization|(?:^|[_.-])auth(?:$|[_.-])/i;

/** Browser output redaction: known secret values, bearer tokens, cookie values, URL credentials, token-named query values and credential-looking runs. */
export function scrub(text        , secrets                   = [])         {
  const out = redactSecretValues(text, secrets)
    .replace(/\b(Bearer|Basic|Token)\s+[A-Za-z0-9._~+/=-]{8,}/gi, '$1 [secret]')
    .replace(/(?<![A-Za-z0-9_.-])(["']?)([A-Za-z0-9_.-]+)\1(\s*(?::\s*[A-Za-z_][\w.<>[\]|]*\s*=(?![=>])|:=|=>|==|[:=])\s*)("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|(?:(?:Bearer|Basic|Token)\s+)?[^\s"']+)/gi, (m, quote        , key        , sep        , value        ) => {
      if (!ASSIGNMENT_KEY.test(key)) return m;
      const q = /^["']/.test(value) ? value[0] : '';
      const scheme = /^(?:Bearer|Basic|Token)\s+/i.exec(value)?.[0] ?? '';
      return `${quote}${key}${quote}${sep}${q}${scheme}[secret]${q}${!q && value.endsWith(',') ? ',' : ''}`;
    })
    .replace(/\b((?:set-)?cookie)(["']?\s*[:=]\s*["']?)[^\r\n"']+/gi, '$1$2[secret]')
    .replace(/\b([a-z][a-z0-9+.-]*:\/\/)[^\s/@:]+(?::[^\s/@]*)?@/gi, '$1[secret]@')
    .replace(/([?&#;])([^=&#\s]+)=([^&#\s"']+)/g, (m, sep        , key        , value        ) => (TOKEN_KEY.test(key) || looksLikeCredential(value) ? `${sep}${key}=[secret]` : m));
  return redactCredentials(out);
}

/** An object key whose value is a credential however it looks, matched with case and separators removed (`X-Auth-Token`, `sessionId`, `set_cookie`). */
const SENSITIVE_KEY = /cookie|authoriz|token|passw|pwd|secret|session|credential|apikey|privatekey|bearer|^(auth|authkey|sid)$/;

/** `scrub` applied to every string and key inside a JSON-like value; a credential-named key's whole value becomes [secret] (null and booleans kept); `skip` names keys left as they are. */
export function scrubDeep   (v   , secrets          , skip = new Set        ())    {
  if (typeof v === 'string') return scrub(v, secrets)     ;
  if (Array.isArray(v)) return v.map((x) => scrubDeep(x, secrets, skip))     ;
  if (v && typeof v === 'object') {
    return Object.fromEntries(Object.entries(v).map(([k, x]) => {
      if (skip.has(k)) return [k, x];
      const blank = x !== null && x !== undefined && typeof x !== 'boolean' && SENSITIVE_KEY.test(k.toLowerCase().replace(/[^a-z]/g, ''));
      return [scrub(k, secrets), blank ? '[secret]' : scrubDeep(x, secrets, skip)];
    }))     ;
  }
  return v;
}
